// The relay job shapes (relay.RelayJob / relay.PlanSpec / relay.RelayResult)
// live in internal/relay — the descriptor vocabulary shared with the enrich
// chain and the api claim surface (the GATE-ruled exported-symbol split).
// This file owns their SQL: every statement over relay_jobs, nothing else.

// relayJobClaimSQL is the ONE conditional statement behind every claim
// (design D3): the WHERE id = (SELECT ...) subselect picks the oldest
// claimable row (relayClaimableSQL) and the single UPDATE flips it to
// claimed with the incoming principal's stamps — SQLite's serialized writes
// make concurrent claimants race-free (the loser matches 0 rows); RETURNING
// hands back the winner without a second statement. The %s slot takes the
// claimant's visibility conjunct (relayClaimWhere), INSIDE the claimability
// subselect: a job outside the claimant's visible set is never picked — an
// invisible library's job reads as nothing-to-claim (invisible ≡ absent).
// When a conjunct is appended the claimability OR is parenthesized first —
// AND binds tighter than OR, and the conjunct must gate the WHOLE
// claimability (a lapsed-lease row re-enters under the same visibility law).
const relayJobClaimSQL = `
UPDATE relay_jobs SET
  state                = 'claimed',
  claim_principal_hash = ?,
  claimed_at           = ?,
  lease_until          = ?
WHERE id = (
  SELECT id FROM relay_jobs
  WHERE %s
  ORDER BY id
  LIMIT 1
)
RETURNING id, purpose, row_id, library_id, plugin_id, plan, state,
  claim_principal_hash, claimed_at, lease_until, result, result_bytes,
  created_at, completed_at, consumed`

// relayClaimableSQL is the claimability predicate every claimant shares: a
// pending row, or a claimed row whose lease lapsed (lazy expiry — decided
// inside the claim predicate, the pairing precedent).
const relayClaimableSQL = "state = 'pending' OR (state = 'claimed' AND lease_until < ?)"

// relayClaimWhere is the claim's visibility conjunct over relay_jobs
// (l6-accounts 11.1) — the WHERE fragment for relayJobClaimSQL's %s slot
// plus the bound args to append after the claim's own stamps. Same shape
// law as visibleWhere (D3/D7 — canonical there); the relay delta is the
// 0-job disjunct: "(library_id = 0 OR library_id IN (?,?,…))" — a 0-job
// (search, library_id 0) carries NO titles, so it is safe for any
// authenticated principal while library-backed jobs must sit in the
// claimant's grant union. A nil or empty visible set fails closed to
// "library_id = 0" — a NARROWER conjunct, never the empty clause.
func relayClaimWhere(v access.Viewer) (clause string, args []any) {
	if v.Admin {
		return "", nil
	}
	if len(v.VisibleLibraryIDs) == 0 {
		return "library_id = 0", nil
	}
	var b strings.Builder
	b.WriteString("(library_id = 0 OR library_id IN (")
	for i := range v.VisibleLibraryIDs {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteByte('?')
	}
	b.WriteString("))")
	args = make([]any, len(v.VisibleLibraryIDs))
	for i, id := range v.VisibleLibraryIDs {
		args[i] = id
	}
	return b.String(), args
}

// CreateRelayJob inserts one pending job row and returns its minted id. The
// plan is marshaled to the JSON blob column; state/consumed/result ride the
// column defaults (pending / 0 / NULL). The caller owns the clock: a zero
// CreatedAt is stamped now (the PutItem precedent). Purpose, row and plugin
// ids are not validated — value-agnostic store (ERROR-FLOOR LAW, doc.go #
// Invariants); the caller owns the enrich|search vocabulary.
func (s *Store) CreateRelayJob(ctx context.Context, job relay.RelayJob) (int64, error) {
	plan, err := json.Marshal(job.Plan)
	if err != nil {
		return 0, fmt.Errorf("store: create relay job %s/%s (plan): %w", job.RowID, job.PluginID, err)
	}
	created := job.CreatedAt
	if created.IsZero() {
		created = time.Now().UTC()
	}
	res, err := s.db.ExecContext(ctx, `
INSERT INTO relay_jobs (purpose, row_id, library_id, plugin_id, plan, created_at)
VALUES (?, ?, ?, ?, ?, ?)`,
		job.Purpose, job.RowID, job.LibraryID, job.PluginID, string(plan), formatTime(created),
	)
	if err != nil {
		return 0, fmt.Errorf("store: create relay job %s/%s: %w", job.RowID, job.PluginID, err)
	}
	id, err := res.LastInsertId()
	if err != nil {
		return 0, fmt.Errorf("store: create relay job %s/%s (id): %w", job.RowID, job.PluginID, err)
	}
	return id, nil
}

// ClaimOldestRelayJob claims the oldest claimable job for principalHash:
// the single conditional UPDATE (relayJobClaimSQL spliced with
// relayClaimWhere(v)) picks and flips the row atomically — exactly one
// concurrent claimant wins, every loser reads (false, nil), and a job
// outside v's visible set reads as nothing claimable (l6-accounts 11.1).
// See-all viewers claim the unfiltered pool, byte-identical to
// pre-accounts; now and leaseUntil are the caller's clock.
func (s *Store) ClaimOldestRelayJob(ctx context.Context, principalHash string, v access.Viewer, now, leaseUntil time.Time) (relay.RelayJob, bool, error) {
	clause, visArgs := relayClaimWhere(v)
	claimable := relayClaimableSQL
	if clause != "" {
		// Parenthesize the claimability OR before ANDing the conjunct: the
		// visibility gate must cover both halves (pending AND lapsed-lease).
		claimable = "(" + claimable + ") AND " + clause
	}
	args := append([]any{
		principalHash, formatTime(now), formatTime(leaseUntil), formatTime(now),
	}, visArgs...)
	rows, err := s.db.QueryContext(ctx, fmt.Sprintf(relayJobClaimSQL, claimable), args...)
	if err != nil {
		return relay.RelayJob{}, false, fmt.Errorf("store: claim relay job: %w", err)
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return relay.RelayJob{}, false, fmt.Errorf("store: claim relay job: %w", err)
		}
		return relay.RelayJob{}, false, nil // nothing claimable — not an error
	}
	job, err := scanRelayJob(rows)
	if err != nil {
		return relay.RelayJob{}, false, fmt.Errorf("store: claim relay job scan: %w", err)
	}
	return job, true, nil
}

// relayJobCompleteGuardSQL is the completion's claim guard (the pre-accounts
// law): the SAME principal's row, still claimed, lease still live.
const relayJobCompleteGuardSQL = `id = ? AND state = 'claimed' AND claim_principal_hash = ? AND lease_until > ?`

// relayClaimLiveSQL classifies a refused completion: does a LIVE claim under
// this principal exist for the id at all (NO visibility conjunct — the
// conjunct's refusal is exactly what is being detected)?
const relayClaimLiveSQL = `SELECT 1 FROM relay_jobs
WHERE id = ? AND state = 'claimed' AND claim_principal_hash = ? AND lease_until > ?`

// relayClaimReleaseSQL returns a released claim to the pool: state back to
// pending, the claim stamps cleared (the hash to its ” insert default — the
// column is NOT NULL; the nullable stamps to NULL). Result and consumed are
// untouched: a claimed row never carries a result and is never consumed, so
// the released row is byte-identical to a fresh pending insert minus id.
const relayClaimReleaseSQL = `UPDATE relay_jobs SET
  state = 'pending', claim_principal_hash = '', claimed_at = NULL, lease_until = NULL
WHERE id = ? AND state = 'claimed' AND claim_principal_hash = ?`

// CompleteRelayJob moves a claimed job to the caller's terminal state (the
// done|failed vocabulary is the caller's) and stores its result;
// result_bytes derives from the stored body length. The guard is the SAME
// principal hash, a LIVE lease, and v's CURRENT visibility conjunct
// (l6-accounts 11.2 — the result-time re-check inside the same atomic
// UPDATE: a principal narrowed since the claim can never ingest; see-all
// splices the empty clause, pre-accounts SQL byte-for-byte). A refusal
// wraps sql.ErrNoRows — the one 409 family upstream (ERROR-FLOOR LAW,
// doc.go # Invariants); completed_at is stamped with the caller's now.
func (s *Store) CompleteRelayJob(ctx context.Context, id int64, principalHash, state string, v access.Viewer, result relay.RelayResult, now time.Time) error {
	blob, err := json.Marshal(result)
	if err != nil {
		return fmt.Errorf("store: complete relay job %d (result): %w", id, err)
	}
	guard := relayJobCompleteGuardSQL
	args := []any{state, string(blob), len(result.Body), formatTime(now), id, principalHash, formatTime(now)}
	if clause, visArgs := relayClaimWhere(v); clause != "" {
		guard += " AND " + clause
		args = append(args, visArgs...)
	}
	res, err := s.db.ExecContext(ctx, `
UPDATE relay_jobs SET
  state        = ?,
  result       = ?,
  result_bytes = ?,
  completed_at = ?
WHERE `+guard,
		args...,
	)
	if err != nil {
		return fmt.Errorf("store: complete relay job %d: %w", id, err)
	}
	if n, err := res.RowsAffected(); err != nil {
		return fmt.Errorf("store: complete relay job %d (affected): %w", id, err)
	} else if n == 0 {
		return s.refuseRelayCompletion(ctx, id, principalHash, v, now)
	}
	return nil
}

// refuseRelayCompletion classifies a 0-row completion (l6-accounts 11.2).
// A stale, foreign, or unknown claim is refused — wrapped sql.ErrNoRows,
// row untouched (a foreign post never frees another principal's live
// claim). A claim LIVE under this principal whose visibility conjunct
// refused (the claimant narrowed since the claim) is RELEASED to the pool
// via relayClaimReleaseSQL, re-checking state+hash against a re-claim.
// Both shapes return the wrapped sql.ErrNoRows; which fired is never
// observable upstream. A see-all viewer is never narrowed: straight
// refusal.
func (s *Store) refuseRelayCompletion(ctx context.Context, id int64, principalHash string, v access.Viewer, now time.Time) error {
	if v.Admin {
		return fmt.Errorf("store: complete relay job %d: %w", id, sql.ErrNoRows)
	}
	var one int
	err := s.db.QueryRowContext(ctx, relayClaimLiveSQL, id, principalHash, formatTime(now)).Scan(&one)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return fmt.Errorf("store: complete relay job %d: %w", id, sql.ErrNoRows)
		}
		return fmt.Errorf("store: complete relay job %d (classify): %w", id, err)
	}
	if _, err := s.db.ExecContext(ctx, relayClaimReleaseSQL, id, principalHash); err != nil {
		return fmt.Errorf("store: complete relay job %d (release): %w", id, err)
	}
	return fmt.Errorf("store: complete relay job %d: viewer narrowed since the claim, released to the pool: %w", id, sql.ErrNoRows)
}

// MarkRelayConsumed flags a job's stored result as consumed (the consult read
// that fed it to Convert — D4). An unknown id floors per the ERROR-FLOOR LAW
// (doc.go # Invariants); re-marking an already-consumed row is a harmless
// rewrite, never an error.
// Whether the row was claimable/done first is the caller's transition graph —
// the store validates none (the SetPairingStatus precedent).
func (s *Store) MarkRelayConsumed(ctx context.Context, id int64) error {
	res, err := s.db.ExecContext(ctx,
		"UPDATE relay_jobs SET consumed = ? WHERE id = ?", true, id)
	if err != nil {
		return fmt.Errorf("store: mark relay job consumed %d: %w", id, err)
	}
	if n, err := res.RowsAffected(); err != nil {
		return fmt.Errorf("store: mark relay job consumed %d (affected): %w", id, err)
	} else if n == 0 {
		return fmt.Errorf("store: mark relay job consumed %d: %w", id, sql.ErrNoRows)
	}
	return nil
}

// CountRelayRounds counts one (row_id, plugin_id) pair's FAILED relay jobs —
// the give-up input the enrich worker feeds into its three-rounds-to-exhausted
// schedule (D5). Done rows never count; another row's or another plugin's
// failures never count. An empty ledger is 0, never an error.
func (s *Store) CountRelayRounds(ctx context.Context, rowID, pluginID string) (int, error) {
	var n int
	if err := s.db.QueryRowContext(ctx, `
SELECT COUNT(*) FROM relay_jobs
WHERE row_id = ? AND plugin_id = ? AND state = 'failed'`,
		rowID, pluginID).Scan(&n); err != nil {
		return 0, fmt.Errorf("store: count relay rounds %s/%s: %w", rowID, pluginID, err)
	}
	return n, nil
}

// scanRelayJob scans one relay_jobs row (through the shared *sql.Row /
// *sql.Rows scanner interface) and round-trips the JSON blob columns and the
// RFC3339Nano stamps. NULL claim/completion stamps read as zero times; a NULL
// result blob reads as the zero relay.RelayResult.
func scanRelayJob(sc scanner) (relay.RelayJob, error) {
	var (
		job         relay.RelayJob
		plan        []byte
		result      []byte
		createdAt   string
		claimedAt   sql.NullString
		leaseUntil  sql.NullString
		completedAt sql.NullString
		consumed    int
	)
	if err := sc.Scan(
		&job.ID, &job.Purpose, &job.RowID, &job.LibraryID, &job.PluginID,
		&plan, &job.State, &job.ClaimPrincipalHash,
		&claimedAt, &leaseUntil, &result, &job.ResultBytes,
		&createdAt, &completedAt, &consumed,
	); err != nil {
		return relay.RelayJob{}, err
	}
	if err := json.Unmarshal(plan, &job.Plan); err != nil {
		return relay.RelayJob{}, fmt.Errorf("plan: %w", err)
	}
	if len(result) > 0 {
		if err := json.Unmarshal(result, &job.Result); err != nil {
			return relay.RelayJob{}, fmt.Errorf("result: %w", err)
		}
	}
	created, err := parseTime(createdAt)
	if err != nil {
		return relay.RelayJob{}, fmt.Errorf("created_at: %w", err)
	}
	job.CreatedAt = created
	if claimedAt.Valid {
		t, err := parseTime(claimedAt.String)
		if err != nil {
			return relay.RelayJob{}, fmt.Errorf("claimed_at: %w", err)
		}
		job.ClaimedAt = t
	}
	if leaseUntil.Valid {
		t, err := parseTime(leaseUntil.String)
		if err != nil {
			return relay.RelayJob{}, fmt.Errorf("lease_until: %w", err)
		}
		job.LeaseUntil = t
	}
	if completedAt.Valid {
		t, err := parseTime(completedAt.String)
		if err != nil {
			return relay.RelayJob{}, fmt.Errorf("completed_at: %w", err)
		}
		job.CompletedAt = t
	}
	job.Consumed = consumed == 1
	return job, nil
}
